
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"LadyJokerAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
			
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.kqe.grw!=undefined){
			gameController.idg=parseInt(tmpMess[1]);	
			gameController.kqe.grw.zps("creditd", "#vrn", [gameController.vfs(tmpMess[1]), true]);	
			
			}	
			
		}
		
